1	import { useCallback } from 'react';
2	
3	/**
4	 * Programmatic sound effects using Web Audio API.
5	 * Uses a singleton AudioContext to avoid leaking contexts on repeated mounts
6	 * (browsers limit to ~6 concurrent AudioContexts).
7	 */
8	
9	let _sharedCtx: AudioContext | null = null;
10	
11	function getSharedAudioContext(): AudioContext {
12	  if (!_sharedCtx || _sharedCtx.state === 'closed') {
13	    _sharedCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
14	  }
15	  // Resume if suspended (e.g. after autoplay policy)
16	  if (_sharedCtx.state === 'suspended') {
17	    _sharedCtx.resume();
18	  }
19	  return _sharedCtx;
20	}
21	
22	export function useSpriteSound() {
23	  /** Soft "bloop" for message received */
24	  const playBloop = useCallback(() => {
25	    try {
26	      const ctx = getSharedAudioContext();
27	      const osc = ctx.createOscillator();
28	      const gain = ctx.createGain();
29	      osc.connect(gain);
30	      gain.connect(ctx.destination);
31	
32	      osc.type = 'sine';
33	      osc.frequency.setValueAtTime(600, ctx.currentTime);
34	      osc.frequency.exponentialRampToValueAtTime(300, ctx.currentTime + 0.1);
35	      gain.gain.setValueAtTime(0.15, ctx.currentTime);
36	      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.15);
37	
38	      osc.start(ctx.currentTime);
39	      osc.stop(ctx.currentTime + 0.15);
40	    } catch {
41	      // Silently fail if audio isn't available
42	    }
43	  }, []);
44	
45	  /** Sparkle sound for interactions */
46	  const playSparkle = useCallback(() => {
47	    try {
48	      const ctx = getSharedAudioContext();
49	      // Two quick ascending tones
50	      for (let i = 0; i < 2; i++) {
51	        const osc = ctx.createOscillator();
52	        const gain = ctx.createGain();
53	        osc.connect(gain);
54	        gain.connect(ctx.destination);
55	
56	        osc.type = 'sine';
57	        const t = ctx.currentTime + i * 0.06;
58	        osc.frequency.setValueAtTime(800 + i * 400, t);
59	        osc.frequency.exponentialRampToValueAtTime(1200 + i * 400, t + 0.08);
60	        gain.gain.setValueAtTime(0.08, t);
61	        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);
62	
63	        osc.start(t);
64	        osc.stop(t + 0.1);
65	      }
66	    } catch {
67	      // Silently fail
68	    }
69	  }, []);
70	
71	  /** Dismiss sound — descending whoosh */
72	  const playDismiss = useCallback(() => {
73	    try {
74	      const ctx = getSharedAudioContext();
75	      const osc = ctx.createOscillator();
76	      const gain = ctx.createGain();
77	      osc.connect(gain);
78	      gain.connect(ctx.destination);
79	
80	      osc.type = 'sine';
81	      osc.frequency.setValueAtTime(500, ctx.currentTime);
82	      osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.3);
83	      gain.gain.setValueAtTime(0.1, ctx.currentTime);
84	      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.35);
85	
86	      osc.start(ctx.currentTime);
87	      osc.stop(ctx.currentTime + 0.35);
88	    } catch {
89	      // Silently fail
90	    }
91	  }, []);
92	
93	  /** Summon chime — plays Pearl Begins.wav at 40% volume */
94	  const playSummonChime = useCallback(() => {
95	    try {
96	      const audio = new Audio('/sounds/pearl-begins.wav');
97	      audio.volume = 0.4;
98	      audio.play();
99	    } catch {
100	      // Silently fail if audio isn't available
101	    }
102	  }, []);
103	
104	  return { playBloop, playSparkle, playDismiss, playSummonChime };
105	}
