1	/**
2	 * Audio management for Daily voice sessions
3	 * Handles mute/unmute, audio level monitoring, and audio device selection
4	 */
5	
6	import type { DailyCall } from '@daily-co/daily-js';
7	
8	import { getClientLogger } from '../client-logger';
9	
10	import type { VoiceAudioState } from './types';
11	
12	const log = getClientLogger('[daily_audio]');
13	
14	/**
15	 * Get current audio state
16	 */
17	export function getAudioState(callObject: DailyCall): VoiceAudioState {
18	  try {
19	    const localParticipant = callObject.participants().local;
20	    
21	    return {
22	      isMuted: localParticipant?.audio === false,
23	      audioLevel: 0, // Will be updated by monitoring
24	      isSpeaking: false, // Will be updated by monitoring
25	    };
26	  } catch (error) {
27	    log.error('Error getting audio state', { error });
28	    return {
29	      isMuted: true,
30	      audioLevel: 0,
31	      isSpeaking: false,
32	    };
33	  }
34	}
35	
36	/**
37	 * Mute local audio
38	 */
39	export async function muteAudio(callObject: DailyCall): Promise<void> {
40	  try {
41	    await callObject.setLocalAudio(false);
42	    log.info('Audio muted');
43	  } catch (error) {
44	    log.error('Error muting audio', { error });
45	    throw error;
46	  }
47	}
48	
49	/**
50	 * Unmute local audio
51	 */
52	export async function unmuteAudio(callObject: DailyCall): Promise<void> {
53	  try {
54	    await callObject.setLocalAudio(true);
55	    log.info('Audio unmuted');
56	  } catch (error) {
57	    log.error('Error unmuting audio', { error });
58	    throw error;
59	  }
60	}
61	
62	/**
63	 * Toggle audio mute state
64	 */
65	export async function toggleAudio(callObject: DailyCall): Promise<boolean> {
66	  try {
67	    const localParticipant = callObject.participants().local;
68	    const isMuted = localParticipant?.audio === false;
69	    
70	    await callObject.setLocalAudio(!isMuted);
71	    
72	    log.info('Audio toggled', { enabled: !isMuted });
73	    return !isMuted;
74	  } catch (error) {
75	    log.error('Error toggling audio', { error });
76	    throw error;
77	  }
78	}
79	
80	/**
81	 * Get available audio devices
82	 */
83	export async function getAudioDevices(): Promise<MediaDeviceInfo[]> {
84	  try {
85	    const devices = await navigator.mediaDevices.enumerateDevices();
86	    return devices.filter((device) => device.kind === 'audioinput');
87	  } catch (error) {
88	    log.error('Error getting audio devices', { error });
89	    return [];
90	  }
91	}
92	
93	/**
94	 * Set audio input device
95	 */
96	export async function setAudioDevice(
97	  callObject: DailyCall,
98	  deviceId: string
99	): Promise<void> {
100	  try {
101	    await callObject.setInputDevicesAsync({
102	      audioDeviceId: deviceId,
103	    });
104	    log.info('Audio device set', { deviceId });
105	  } catch (error) {
106	    log.error('Error setting audio device', { error, deviceId });
107	    throw error;
108	  }
109	}
110	
111	/**
112	 * Get current audio input device
113	 */
114	export async function getCurrentAudioDevice(
115	  callObject: DailyCall
116	): Promise<string | null> {
117	  try {
118	    const { mic } = await callObject.getInputDevices();
119	    return (mic as MediaDeviceInfo)?.deviceId || null;
120	  } catch (error) {
121	    log.error('Error getting current audio device', { error });
122	    return null;
123	  }
124	}
125	
126	/**
127	 * Start audio processing (noise cancellation, echo cancellation, AGC)
128	 */
129	export async function startAudioProcessing(
130	  callObject: DailyCall
131	): Promise<void> {
132	  try {
133	    await callObject.updateInputSettings({
134	      audio: {
135	        processor: {
136	          type: 'noise-cancellation',
137	        },
138	      },
139	    });
140	    log.info('Audio processing started');
141	  } catch (error) {
142	    log.error('Error starting audio processing', { error });
143	    throw error;
144	  }
145	}
